-- ============================================================
-- IDCC 0016 — MINIMA CONVENTIONNELS STRUCTURÉS (calculs/alertes.rs)
--
-- Les grilles de la migration 0113 sont ÉDITORIALES (JSON affiché par
-- le Chakrram). Cette table en reprend, ligne à ligne et sans un chiffre
-- de plus, le premier tableau de chaque grille pour que le moteur puisse
-- comparer le salaire de base au minimum du coefficient :
--
--   • unite 'horaire' : taux horaire conventionnel du palier (marchandises
--     ouvriers/employés/TAM, déménagement, logistique, sanitaire) ;
--   • unite 'mensuel' : salaire mensuel professionnel garanti (voyageurs)
--     ou paiement mensuel minimum des cadres, pour heures_base heures.
--
-- anciennete_mois = seuil du palier (0 = à l'embauche, 6 = après 6 mois…).
-- Pour les cadres, l'ancienneté s'apprécie dans le GROUPE (art. 5 CCNA 4) :
-- le simulateur n'a que l'ancienneté dans l'entreprise, l'alerte le dit.
--
-- Écartés volontairement : garanties annuelles (GAR/RAG, contrôle sur
-- l'année civile), majorations DC 0/1/2 du déménagement (conditions
-- d'emploi), majoration de 10 % région parisienne des cadres.
-- Avant date_debut d'une grille, aucun minimum n'est connu : pas d'alerte.
-- Mêmes sources que 0113 (colonne source) ; génération depuis ces
-- tableaux, consultation du 12 août 2026.
-- ============================================================
CREATE TABLE ccn_minima (
    id              INTEGER PRIMARY KEY,
    idcc            TEXT    NOT NULL,
    branche         TEXT    NOT NULL,
    categorie       TEXT    NOT NULL CHECK (categorie IN ('ouvriers','employes','tam','cadres')),
    coefficient     TEXT    NOT NULL,
    emploi          TEXT,
    anciennete_mois INTEGER NOT NULL,
    unite           TEXT    NOT NULL CHECK (unite IN ('horaire','mensuel')),
    montant         TEXT    NOT NULL,
    heures_base     TEXT    NOT NULL,
    date_debut      TEXT    NOT NULL,
    date_fin        TEXT,
    source          TEXT    NOT NULL,
    UNIQUE (idcc, branche, categorie, coefficient, anciennete_mois, date_debut)
);

